urlset:
{%- for entry in entries %}
    {% set route = entry.permalink | replace(from=config.base_url ~ '/', to='') | trim_start_matches(pat='zh/') | trim_start_matches(pat='ko/') %}

        {{ entry.permalink | escape_xml | safe }}
        {% if build %}{{ build.modified }}{% endif %}
        {% for code in ['en', 'ko', 'zh'] %}{% set prefix = '' %}{% set tag = code %}{% if code != 'en' %}{% set prefix = code ~ '/' %}{% endif %}{% if code == 'zh' %}{% set tag = 'zh-Hans' %}{% endif %}{% endfor %}


{%- endfor %}
